#!/usr/bin/env python3
"""X-01: evidence-indexed capability matrix over executed POCs."""
from __future__ import annotations
import hashlib,json,platform
from datetime import datetime,timezone
from pathlib import Path
P=Path(__file__).resolve().parent;OUT=P/'output';ROOT=P.parents[1]
def row(cap,tool,poc,structure,coverage,pos,neg,amb,limit=''):
 return {'capability':cap,'tool':tool,'poc':poc,'artifact':f'poc/{poc}/output/results.json','exact_structure':structure,'coverage':coverage,'positive_fixture':pos,'negative_fixture':neg,'ambiguous_fixture':amb,'limit':limit}
def main():
 OUT.mkdir(parents=True,exist_ok=True);rows=[
 row('segmentation','ACE/ERG token lattice','nlp-04','initial/internal tokens with Unicode [start,end) spans','full','six reconstructable fixtures','invalid span rejected by contract','22 competing analyses retained'),
 row('morphology','ERG MRS variables','nlp-01','variable property maps and derivation lexical nodes','full','inflected grammatical clauses','ungrammatical fixture has zero reading','multiple derivations retain features'),
 row('syntax','ACE/ERG + Link Grammar','nlp-06','HPSG derivation tree and typed linkage graph','partial','five fixtures parsed by both','one parsed by neither','exclusive and shared candidates attributed','Link Grammar remains secondary, never truth'),
 row('HPSG','ACE/ERG','nlp-01','ranked derivation and syntax tree','full','nine controlled constructions','explicit no-analysis record','ranked parses preserved'),
 row('MRS/EDS/DMRS','PyDelphin','nlp-02','MRS EPs/HCONS plus EDS nodes/edges and DMRS nodes/links','full','18 well-formed MRS','non-well-formed candidates recorded','21 candidates preserved'),
 row('semantic roles','ERG/PyDelphin + PropBank candidates','nlp-04','labelled ARG relations with derived span support','full','291 supported role relations','unsupported count measured','roles remain analysis-relative'),
 row('lexical relations','WordNet/VerbNet/FrameNet/SemLink','lex-07','attributed candidate edges across resources','partial','contrast lookups reach 102 WordNet/SUMO edges','absent/unsupported mappings retained','no contextual winner selected','candidate generation, not WSD'),
 row('temporal representation','Allen + Reichenbach + persistence layer','time-07','revision events over Allen/ERS/persistence candidates','full','consistent anchor revision','contradiction remains explicit','alternative temporal histories preserved'),
 row('coreference','Coreferee/CoreNLP adapters','dlg-12','attributed mention chains and ambiguous mentions','partial','English/French chains','unresolved mentions retained','two ambiguous mentions preserved','baseline, not universal resolver'),
 row('quantification','ERG MRS + Z3 scope adapter','nlp-03','quantifier EPs, HCONS and enumerated readings','partial','2- and 3-quantifier fixtures','ill-formed MRS excluded','34 adapter readings','scope enumeration is repository adapter'),
 row('scope','ERG MRS + Z3','nlp-03','underspecified HCONS and canonical resolved permutations','partial','canonical readings enumerated','unknown-predicate fallback attributed','attachment/scope alternatives coexist','resolved readings come from the explicit Z3 adapter'),
 row('connectors','ERG + attributed SDRT import','dlg-05','labelled discourse edges across turns','partial','508 discourse relations','no automatic general SDRT parse claim','crossing/nonlocal links retained','gold import; automatic parser absent'),
 row('IPA transcription','Epitran','sem-01','attributed IPA candidate with producer and warnings','partial','English/French transcriptions','unsupported coverage warns','Epitran and Flite candidates coexist','Flite output is ARPABET, never called IPA'),
 row('phonological features','Epitran/feature adapter','sem-02','segment feature vectors with explicit unknowns','partial','explainable feature distance','unknown segments flagged','multiple candidates remain attributed','unknown and uncovered segments remain explicit'),
 row('WFST transformations','weighted form-relation engine','sem-03','composable weighted paths with rule provenance','full','six composed paths','negative query yields no path','alternative weighted paths retained'),
 row('G2P multiple candidates','Phonetisaurus','sem-04','n-best pronunciation strings','partial','all six held-out words have multiple candidates','OOV training separation checked','n-best retained','API omits scores, alignments and lattice'),
 row('cross-representation retrieval','multiplane graph retrieval','sem-05','plane-specific nodes/edges and ranked results','full','10 results across 5 planes','no semantic identity invented','no global selection collapse'),
 row('incremental progression','candidate-based ISU','dlg-07','state before/after, candidate updates and reversible delta','full','six turn updates','one no-decision step','close interpretations retained'),
 row('communicative functions','Soar + Z3 planner','comm-01','prelinguistic plans with goal/content/commitment/style/provenance','full','assertion/answer/clarification/refusal','silence is explicit zero-unit plan','competing behaviour types remain distinct'),
 row('inter-turn discourse relations','STAC SDRT importer','dlg-05','directed labelled cross-turn/cross-speaker graph','partial','412 cross-turn relations','missing thread IDs marked absent','222 nonlocal and crossing relations preserved','corpus import, not automatic parser'),
 row('formalized dialogue context','typed DGB + ISU','dlg-06','participants/moves/facts/QUD/obligations/pending records','full','active and resolved QUD','unresolved fields explicit','alternatives stored on records'),
 row('high-level cultural patterns','Switchboard/Reddit induction','cult-01','anonymous sequential patterns with occurrence evidence','partial','45,426 real Switchboard evidence rows','exceptions and held-out errors retained','12 anonymous patterns evaluated','corpus-specific, not universal culture')]
 hashes={}
 for r in rows:
  path=ROOT/r['artifact'];assert path.exists(),path;data=json.loads(path.read_text());assert data not in ({},[]),path;hashes[r['poc']]=hashlib.sha256(path.read_bytes()).hexdigest()
 validations={'all_announced_capabilities_present':len(rows)==22 and len({r['capability'] for r in rows})==22,'every_cell_names_tool_and_exact_structure':all(r['tool'] and r['exact_structure'] for r in rows),'positive_negative_ambiguous_evidence_each':all(r['positive_fixture'] and r['negative_fixture'] and r['ambiguous_fixture'] for r in rows),'no_empty_coverage_cell':all(r['coverage'] in {'full','partial','resource-only','not-provided'} for r in rows),'limits_explicit_for_non_full':all(r['limit'] for r in rows if r['coverage']!='full'),'all_artifacts_exist_and_parse':len(hashes)>=18,'no_architectural_component_relabelled_external':all(r['tool']!='architecture' for r in rows)};assert all(validations.values()),validations
 lines=['# X-01 capability matrix','','| Capability | Tool | Exact structure | Coverage | Limit |','|---|---|---|---|---|']+[f"| {r['capability']} | {r['tool']} | {r['exact_structure']} | {r['coverage']} | {r['limit']} |" for r in rows];(OUT/'capability-matrix.md').write_text('\n'.join(lines)+'\n');(OUT/'results.json').write_text(json.dumps({'matrix':rows,'artifact_sha256':hashes,'validations':validations},ensure_ascii=False,indent=2)+'\n');counts={x:sum(r['coverage']==x for r in rows) for x in ['full','partial','resource-only','not-provided']};(OUT/'summary.json').write_text(json.dumps({'capabilities':len(rows),'coverage_counts':counts,'evidence_artifacts':len(hashes),'verdict':'GO_EVIDENCE_INDEXED_CAPABILITY_MATRIX'},indent=2)+'\n');(OUT/'versions-and-parameters.json').write_text(json.dumps({'generated_at':datetime.now(timezone.utc).isoformat(),'platform':platform.platform(),'matrix_schema':'capability/tool/poc/artifact/exact_structure/coverage/positive/negative/ambiguous/limit'},indent=2)+'\n');print(f'X-01: {len(rows)} capabilities mapped to exact produced structures; GO')
if __name__=='__main__':main()
